","reason":"Envolve recolher e organizar dados utilizando o contexto técnico de sistemas de informação geográfica (SIG).","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/49321bf1-b20e-4aa1-a721-67b0ddfcea73","category":"H1","reason":"A atividade é aconselhamento profissional baseado em conhecimento especializado de produtos, acessórios, utilização e manutenção em audiologia. Os produtos concretos não são, eles próprios, a competência.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/4932c6e3-f6c7-49bf-bf66-f8508237054f","category":"S2","reason":"Refere-se à disciplina e autogestão necessárias para concluir tarefas nos prazos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/4934c105-5e90-4874-9957-78eceef1a13c","category":"S1","reason":"A finalidade central é persuadir potenciais clientes e comunicar valor para realizar vendas; proatividade é um requisito complementar, não o significado principal.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/4938b245-1312-4e8f-adc9-a3ae031e4d70","category":"H1","reason":"Trata de decisões especializadas relativas ao cultivo e à propagação de plantas.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/493a1805-6caa-4cda-8fd3-6495ec8ea451","category":"H3","reason":"Consiste na execução de técnicas e processos estruturados de preparação de alimentos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/493b20c2-c435-449a-896e-0af057c41fef","category":"H3","reason":"Descreve as etapas e o fluxo estruturado da produção cinematográfica.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/493fb8bf-d880-4499-b374-b1ecb0df4b50","category":"H1","reason":"É conhecimento especializado sobre medicamentos à base de plantas e respetivos efeitos e usos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/4940d889-a185-4176-a920-46b88cbe0d8c","category":"H2","reason":"Refere-se a componentes e acessórios concretos para cabos elétricos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/494f3e5b-c9a8-4d55-97bc-13ea16b6a59a","category":"H3","reason":"Descreve processos técnicos e etapas de transformação e conservação do leite.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/4959697d-3a24-4f46-af0c-b752318e6c54","category":"H2","reason":"ObjectStore é um programa informático concreto de gestão de bases de dados.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/4959d8c3-40dd-404d-9b29-ec7501bf5c39","category":"H3","reason":"Envolve o processo técnico de revisão, seleção e encaminhamento de imagens para montagem cinematográfica.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/495ce586-09d7-4cec-83d7-2821be6590c4","category":"H2","reason":"Refere-se a linguagens de programação concretas usadas para desenvolver contratos inteligentes.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/49618378-8e17-4418-b63e-6247e97660bf","category":"H2","reason":"Abrange ferramentas e materiais concretos utilizados em operações de torno.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/496932f1-0b6b-4f73-9432-d95c7ddcd43b","category":"H4","reason":"O recrutamento é uma atividade estruturada de gestão de recursos humanos e seleção de pessoal.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/496fd702-885e-488c-a48a-27e0ab692292","category":"S1","reason":"Consiste em atender pedidos pessoais de hóspedes e prestar apoio direto ao cliente. Não descreve gestão de operações de hospitalidade.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/49708c50-fa54-4384-be24-4ac1ff8dbf64","category":"H3","reason":"Envolve monitorização operacional estruturada de atividades de pesca para gestão de existências.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/497705d7-7a03-4a68-99f3-69d2de9366f4","category":"H3","reason":"Consiste em aplicar procedimentos formais de avaliação e mitigação de riscos em serviços sociais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/497ac2d8-6a9c-45d1-8149-e7aa2d9e2cff","category":"H1","reason":"É apoio/intervenção profissional especializado com crianças e adolescentes vítimas de abuso sexual; a interação empática é essencial, mas serve uma prática de cuidado especializada.","certainty":"adjudicated_high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
